cd /testbed && patch -p1 <<'PATCH'
--- a/tokio-util/tests/time_delay_queue.rs
+++ b/tokio-util/tests/time_delay_queue.rs
@@ -169,6 +169,54 @@
 }

 #[tokio::test]
+async fn remove_last_entry_wakes() {
+    time::pause();
+
+    let mut queue = task::spawn(DelayQueue::new());
+    let key = queue.insert("foo", Duration::from_secs(100));
+
+    assert_pending!(poll!(queue));
+    assert!(!queue.is_woken());
+
+    let entry = queue.remove(&key);
+    assert_eq!(entry.into_inner(), "foo");
+
+    assert!(queue.is_woken());
+    assert!(assert_ready!(poll!(queue)).is_none());
+}
+
+#[tokio::test]
+async fn try_remove_last_entry_wakes() {
+    time::pause();
+
+    let mut queue = task::spawn(DelayQueue::new());
+    let now = Instant::now();
+    let key1 = queue.insert_at("foo", now + ms(100));
+    let key2 = queue.insert_at("bar", now + ms(100));
+
+    assert_pending!(poll!(queue));
+    assert!(!queue.is_woken());
+
+    let entry = queue.try_remove(&key1).unwrap();
+    assert_eq!(entry.into_inner(), "foo");
+    assert!(!queue.is_woken());
+    assert_pending!(poll!(queue));
+
+    assert!(queue.try_remove(&key1).is_none());
+    assert!(!queue.is_woken());
+
+    let entry = queue.try_remove(&key2).unwrap();
+    assert_eq!(entry.into_inner(), "bar");
+    assert!(queue.is_woken());
+    assert!(assert_ready!(poll!(queue)).is_none());
+
+    assert!(queue.try_remove(&key2).is_none());
+    assert!(!queue.is_woken());
+}
+
+#[tokio::test]
 async fn reset_entry() {
     time::pause();

PATCH
cargo test --offline -p tokio-util --features full --test time_delay_queue last_entry_wakes

